import type { ClaraDomainOption } from '../components/molecules/ClaraDomainDropdown';
import {
  CLARA_BRAND_GUIDANCE_PROJECT_KEY,
  CLARA_CATEGORY_PROJECT_KEY,
  CLARA_CONSUMER_PROJECT_KEY,
  CLARA_VALUE_CREATION_PROJECT_KEY,
} from './projectKeys';

export const CLARA_DOMAIN_OPTIONS: ClaraDomainOption[] = [
  {
    label: 'Clara: Category',
    value: CLARA_CATEGORY_PROJECT_KEY,
    description:
      'Gain Brand Participation Insights from Atlantia and Kantar surveys',
  },
  {
    label: 'Clara: Brand Guidance',
    value: CLARA_BRAND_GUIDANCE_PROJECT_KEY,
    description:
      "Gain global insights from Kantar to better understand your Brand's marketing power.",
  },
  {
    label: 'Clara: Consumer Hours',
    value: CLARA_CONSUMER_PROJECT_KEY,
    description: 'Generate consumer insights from market research interviews',
  },
  {
    label: 'Clara: Value Creation',
    value: CLARA_VALUE_CREATION_PROJECT_KEY,
    description: 'Gain insights on Volume, NR and CORES performance',
  },
];
